    },
    {
      "id": 2,
      "claim": "The derivative of net benefit with respect to quantity equals marginal benefit minus marginal cost (d(NetBenefit)/dQ = MB – MC).",
      "evidence": "By definition, MB = d(TB)/dQ and MC = d(TC)/dQ; net benefit = TB – TC.",
      "weight": 0.2,
      "depends_on": [1]
    },
    {
      "id": 3,
      "claim": "At the interior maximum of net benefit, this derivative is zero, so MB = MC.",
      "evidence": "First‑order condition for a maximum: set the derivative of the objective function to zero.",
      "weight": 0.3,
      "depends_on": [2]
    },
    {
      "id": 4,
      "claim": "Therefore the consumer stops eating when the marginal benefit of the next cookie equals its marginal cost; any additional cookie would lower net benefit.",
      "evidence": "If MB > MC, consuming another unit raises net benefit; if MB < MC, it lowers net benefit. Equality is the indifference point where the consumer is just indifferent to consuming one more.",
      "weight": 0.3,
      "depends_on": [3]
    }
  ],
